STATION_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Station games</title><style>
:root{color-scheme:dark;font:15px/1.45 Inter,ui-sans-serif,system-ui,sans-serif;background:#171715;color:#e8e3d9}*{box-sizing:border-box}body{margin:0;background:#171715}button,input{font:inherit}.topbar{height:52px;border-bottom:1px solid #383731;background:#1d1d1a;display:flex;align-items:center;justify-content:space-between;padding:0 24px}.topbar strong{font-size:15px}.topbar a{color:#aaa69b;text-decoration:none}.layout{max-width:1120px;margin:0 auto;padding:24px;display:grid;grid-template-columns:260px 1fr;gap:24px}.nav{border-right:1px solid #383731;min-height:calc(100vh - 100px);padding-right:20px}.nav a{display:block;padding:9px 10px;color:#c8c2b7;text-decoration:none;border-radius:6px}.nav a.active{background:#2a2924;color:#fff}.content h1{font-size:24px;line-height:1.2;margin:0 0 8px}.muted{color:#aaa69b}.panel{border:1px solid #3c3a34;background:#20201d;border-radius:8px;margin-top:20px}.panel-head{padding:14px 16px;border-bottom:1px solid #3c3a34;display:flex;justify-content:space-between;align-items:center}.panel-body{padding:16px}.form-row{display:grid;grid-template-columns:1fr auto auto;gap:8px}label{display:block;font-weight:600;margin-bottom:6px}input{width:100%;background:#171715;color:#eee8dc;border:1px solid #4a4840;border-radius:6px;padding:10px 11px}button{border:1px solid #4a4840;border-radius:7px;padding:9px 13px;background:#2a2924;color:#eee8dc;cursor:pointer}button.primary{background:#b58b55;border-color:#b58b55;color:#17130f;font-weight:700}button.danger{color:#efb0a8;border-color:#70443e}.status{font-family:ui-monospace,SFMono-Regular,monospace;color:#bdb7ab}.seats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#3c3a34;border-top:1px solid #3c3a34}.seat{background:#20201d;padding:20px;text-align:center}.seat h2{font-size:17px;margin:0 0 12px}.seat img{display:block;width:min(100%,300px);aspect-ratio:1;margin:auto;background:#fff}.seat p{margin:10px 0 0;color:#aaa69b}.recovery{border-color:#75564a}.recovery .panel-head{color:#e5b9a2}@media(max-width:760px){.layout{display:block;padding:16px}.nav{display:none}.form-row{grid-template-columns:1fr}.seats{grid-template-columns:1fr}.topbar{padding:0 16px}}
</style></head><body><header class="topbar"><strong>Chess Gantry / Station</strong><a href="/">System dashboard</a></header><main class="layout"><nav class="nav"><a class="active" href="/station">Station game</a><a href="/">Hardware</a></nav><section class="content"><h1>Two-player station game</h1><p class="muted">Set the physical board to the standard position. Create a game and give one QR code to each player. There is no chess clock or idle timeout.</p><section class="panel"><div class="panel-head"><strong>Game setup</strong><span id="status" class="status">Idle</span></div><div class="panel-body"><label for="confirmation">Physical confirmation</label><div class="form-row"><input id="confirmation" value="STATION BOARD AND CHUTES READY"><button id="create" class="primary">Create next game</button><button id="resume">Resume saved game</button><button id="stop" class="danger">Stop current game</button></div></div><div id="codes" class="seats" hidden><article class="seat"><h2>White seat</h2><img id="whiteQr" alt="QR code for White"><p id="whiteState">Waiting for player</p></article><article class="seat"><h2>Black seat</h2><img id="blackQr" alt="QR code for Black"><p id="blackState">Waiting for player</p></article></div></section><section id="recovery" class="panel recovery" hidden><div class="panel-head"><strong>Physical move needs reconciliation</strong></div><div class="panel-body"><p class="muted">Inspect the board and pending move before continuing.</p><label for="recoveryText">Recovery confirmation</label><div class="form-row"><input id="recoveryText" placeholder="STATION PHYSICAL STATE VERIFIED"><button id="apply">Move completed</button><button id="discard">Move did not happen</button></div></div></section></section></main><script>
const $=id=>document.getElementById(id);async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.error||'Request failed');return j.result||j}function render(s){$('status').textContent=s.error?`Failed: ${s.error}`:`${s.state||'idle'}${s.result?' / '+s.result:''}`;$('recovery').hidden=!(s.state==='failed'&&s.pending_uci);$('resume').disabled=s.state!=='resume_required';if(s.game_id){$('codes').hidden=false;$('whiteQr').src='/api/station/qr?seat=white&t='+Date.now();$('blackQr').src='/api/station/qr?seat=black&t='+Date.now();$('whiteState').textContent=s.joined.white?(s.left.white?'Left game':'Connected'):'Waiting for player';$('blackState').textContent=s.joined.black?(s.left.black?'Left game':'Connected'):'Waiting for player'}else $('codes').hidden=true}async function refresh(){try{render(await api('/api/station/status'))}catch(e){$('status').textContent=e.message}}$('create').onclick=async()=>{try{render(await api('/api/station/create',{method:'POST',body:JSON.stringify({confirmation:$('confirmation').value})}))}catch(e){$('status').textContent=e.message}};$('resume').onclick=async()=>{try{render(await api('/api/station/resume',{method:'POST',body:JSON.stringify({confirmation:$('confirmation').value})}))}catch(e){$('status').textContent=e.message}};$('stop').onclick=async()=>{try{render(await api('/api/station/stop',{method:'POST',body:'{}'}))}catch(e){$('status').textContent=e.message}};for(const [id,action] of [['apply','apply'],['discard','discard']])$(id).onclick=async()=>{try{render(await api('/api/station/reconcile/'+action,{method:'POST',body:JSON.stringify({confirmation:$('recoveryText').value})}))}catch(e){$('status').textContent=e.message}};setInterval(refresh,1000);refresh();
</script></body></html>"""

STATION_PLAYER_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>Station chess</title><style>
:root{color-scheme:dark;font:15px/1.4 Inter,ui-sans-serif,system-ui,sans-serif;background:#171715;color:#e8e3d9}*{box-sizing:border-box}body{margin:0;background:#171715}.topbar{height:52px;border-bottom:1px solid #383731;background:#1d1d1a;padding:0 16px;display:flex;align-items:center;justify-content:space-between}.app{width:min(100%,620px);margin:0 auto;padding:16px}.board{display:grid;grid-template-columns:repeat(8,1fr);width:100%;aspect-ratio:1;border:1px solid #4a473f}.sq{position:relative;border:0;border-radius:0;padding:0;font-size:clamp(28px,9vw,56px);display:grid;place-items:center;color:#17130f;text-shadow:0 1px #fff8}.light{background:#d8c9aa}.dark{background:#8d6d4c}.sq.selected{box-shadow:inset 0 0 0 4px #e0ad55}.sq.target::after{content:'';position:absolute;width:22%;aspect-ratio:1;border-radius:50%;background:#4d704c}.status{min-height:48px;margin:0;padding:12px 0;color:#b8b1a4}.error{color:#e69b91}.actions{display:flex;gap:8px}.actions button{flex:1;padding:11px;border-radius:7px;border:1px solid #4a4840;background:#24231f;color:#e8e3d9;font-weight:600}.actions .danger{color:#efb0a8;border-color:#70443e}
</style></head><body><header class="topbar"><strong id="seat">Joining station</strong><span id="turn"></span></header><main class="app"><div id="board" class="board"></div><p id="status" class="status">Connecting...</p><div class="actions"><button id="draw">Offer draw</button><button id="leave">Leave game</button><button id="resign" class="danger">Resign</button></div></main><script>
let token=location.hash.slice(1),state=null,selected=null,busy=false;const symbols={P:'♙',N:'♘',B:'♗',R:'♖',Q:'♕',K:'♔',p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚','.':''};if(token)sessionStorage.setItem('station-seat-token',token);else token=sessionStorage.getItem('station-seat-token')||'';history.replaceState(null,'',location.pathname);async function api(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,...body})});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.error||'Request failed');return j.result}function canonical(display){const row=Math.floor(display/8),col=display%8;return state.seat==='white'?(7-row)*8+col:row*8+(7-col)}function name(index){return'abcdefgh'[index%8]+(Math.floor(index/8)+1)}function draw(){const root=$('board');root.innerHTML='';const flat=(state.rows||[]).slice().reverse().join('');for(let i=0;i<64;i++){const c=canonical(i),square=name(c),piece=flat[c]||'.',button=document.createElement('button');button.className='sq '+(((c%8+Math.floor(c/8))%2)?'dark':'light');button.textContent=symbols[piece]||'';button.setAttribute('aria-label',square);if(selected===square)button.classList.add('selected');if(selected&&(state.legal_moves||[]).some(m=>m.slice(0,2)===selected&&m.slice(2,4)===square))button.classList.add('target');button.onclick=()=>choose(square);root.appendChild(button)}}async function choose(square){if(!state.your_turn||busy)return;if(!selected){if((state.legal_moves||[]).some(m=>m.startsWith(square)))selected=square;draw();return}let candidates=(state.legal_moves||[]).filter(m=>m.startsWith(selected+square));if(!candidates.length){selected=null;return choose(square)}let move=candidates[0];if(candidates.length>1){const choice=(prompt('Promotion piece: q, r, b, or n','q')||'q').toLowerCase();move=candidates.find(m=>m.endsWith(choice))||candidates[0]}busy=true;try{state=await api('/api/station/move',{uci:move,expected_ply:state.history.length});selected=null;render()}catch(e){showError(e)}finally{busy=false}}function showError(e){$('status').textContent=e.message;$('status').className='status error'}function render(){if(!state)return;$('seat').textContent=`${state.seat[0].toUpperCase()+state.seat.slice(1)} / ${state.game_id}`;$('turn').textContent=state.result?state.result:`${state.turn} to move`;$('status').className='status';$('status').textContent=state.error||(state.draw_offer&&state.draw_offer!==state.seat?'Opponent offered a draw. Press Offer draw to accept.':({waiting_players:'Waiting for the other player.',homing:'Homing the gantry.',playing:state.your_turn?'Your move.':'Waiting for opponent.',executing:'Mirroring move on the physical board.',finished:`Game finished: ${state.result}`,failed:'Operator attention required.',stopped:'Game stopped.'}[state.state]||state.state));draw()}async function poll(){if(busy)return;try{state=await api(state?'/api/station/state':'/api/station/join',{});render()}catch(e){showError(e)}}$('draw').onclick=async()=>{state=await api('/api/station/draw',{});render()};$('resign').onclick=async()=>{if(confirm('Resign this game?')){state=await api('/api/station/resign',{});render()}};$('leave').onclick=async()=>{if(confirm('Leave this game? This awards the game to your opponent.')){state=await api('/api/station/leave',{});sessionStorage.removeItem('station-seat-token');render()}};setInterval(poll,650);poll();
</script></body></html>"""
